# shellcheck source=scripts/lib-quiet.sh
source "$PLUGIN_ROOT/scripts/lib-quiet.sh"
larch_quiet_init
[[ -f "$CLI" ]] || { larch_err "tally-code-votes.sh: missing python/cli.py at $CLI"; exit 2; }
