sanitize_classification_text_cell() {
    local cell
    cell=$(printf '%s' "${1:-}" | tr '\011\015\012' '   ' | sed 's/[[:space:]]*|[[:space:]]*/|/g')
    case "$cell" in
        [=+-@]*) printf "'%s" "$cell" ;;
        *) printf '%s' "$cell" ;;
    esac
}

reviewer_slots_for_tsv() {
    printf '%s\n' "${1:-}" | awk -F',' '
      {
        out = ""
        for (i = 1; i <= NF; i++) {
          gsub(/[\t\r\n]/, " ", $i)
          gsub(/^[[:space:]]+|[[:space:]]+$/, "", $i)
          if ($i != "") out = (out == "" ? $i : out "|" $i)
        }
        print out
      }'
}

kv_value() {
    local key="$1"
    awk -F= -v k="$key" '$1 == k { print substr($0, length(k) + 2); found=1 } END { if (!found) print "" }'
}

sanitize_vote_cell() {
    case "${1:-}" in
        YES|NO|JUDGE_ERROR) printf '%s' "$1" ;;
        *) printf '' ;;
    esac
}

sanitize_correctness_cell() {
    case "${1:-}" in
        true|partially-true|false-positive|uncertain) printf '%s' "$1" ;;
        *) printf '' ;;
    esac
}

sanitize_severity_cell() {
    case "${1:-}" in
        blocker|major|minor|nit|uncertain) printf '%s' "$1" ;;
        *) printf '' ;;
    esac
}

sanitize_quality_cell() {
    case "${1:-}" in
        excellent|good|adequate|weak|no-fix|uncertain) printf '%s' "$1" ;;
        *) printf '' ;;
    esac
}

sanitize_uncertain_cell() {
    case "${1:-}" in
        true|false) printf '%s' "$1" ;;
        *) printf 'true' ;;
    esac
}

sanitize_result_cell() {
    case "${1:-}" in
        accepted|rejected|neutral) printf '%s' "$1" ;;
        *) printf '' ;;
    esac
}

parse_vote_rating_for() {
    local voter_file="$1" ballot_id="$2" parsed rc
    set +e
    parsed=$(python3 "$CLI" voting parse-judge-vote "$voter_file" "$ballot_id" 2>/dev/null)
    rc=$?
    set -e
    if [[ "$rc" -ne 0 ]]; then
        printf 'WARN=%s\n' "judge vote/rating parser failed for $(basename "$voter_file") $ballot_id (rc=$rc); treating vote as JUDGE_ERROR" >&3
        printf 'PARSED_VOTE=JUDGE_ERROR\n'
        printf 'PARSED_CORRECTNESS=\n'
        printf 'PARSED_SEVERITY=\n'
        printf 'PARSED_QUALITY=\n'
        printf 'PARSED_UNCERTAIN=true\n'
    else
        printf '%s\n' "$parsed"
    fi
}

